#!/bin/bash
set -euxo pipefail
exec > >(tee -a /var/log/hw4-startup.log) 2>&1

apt-get update
apt-get install -y python3-venv python3-pip

mkdir -p /opt/hw4

echo '' | base64 -d > /opt/hw4/server.py
echo 'Z29vZ2xlLWNsb3VkLXN0b3JhZ2UKZ29vZ2xlLWNsb3VkLWxvZ2dpbmcKCg==' | base64 -d > /opt/hw4/requirements.txt

python3 -m venv /opt/hw4/venv
/opt/hw4/venv/bin/pip install -r /opt/hw4/requirements.txt

cat > /etc/systemd/system/hw4-server.service <<'EOF'
[Unit]
Description=HW4 Python HTTP Server
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=/opt/hw4
Environment=BUCKET=cs528-hw2-pgeesala
Environment=PORT=8080
Environment=REPORTER_URL=http://10.128.0.5:8081
ExecStart=/opt/hw4/venv/bin/python -u /opt/hw4/server.py
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable --now hw4-server
